import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";
import { Editor } from "@tinymce/tinymce-react";
import { plugins } from "../constants/plugins";
import { toolbars } from "../constants/toolbars";
import { Container } from "react-bootstrap";
import api from "../api";

const EditChapter = () => {
  const { bookId, chapterId } = useParams();
  const [chapter, setChapter] = useState({});
  const [newChapterTitle, setNewChapterTitle] = useState("");
  const [editorValue, setEditorValue] = useState("");
  const [newChapterContent, setNewChapterContent] = useState("");

  useEffect(() => {
    const fetchChapter = async () => {
      try {
        const response = await api.get(
          `/api/books/${bookId}/chapter/${chapterId}`
        );
        setChapter(response.data);
      } catch (err) {
        console.error("Error fetching chapters:", err);
      }
    };
    fetchChapter();
  }, [bookId, chapterId]);

  const onEditorInputChange = (newValue, editor) => {
    setEditorValue(newValue);
    setNewChapterContent(editor.getContent({ format: "text" }));
  };

  return (
    <Container>
      <Editor
        apiKey="88pb83a1e7lg1vuj66gj6osihy71r5ebdtldqvohimk45a8s"
        init={{ plugins: plugins, toolbar: toolbars }}
        onEditorChange={(newValue, editor) =>
          onEditorInputChange(newValue, editor)
        }
        onInit={(evt, editor) =>
          setNewChapterContent(editor.getContent({ format: "text" }))
        }
        value={editorValue}
        initialValue={"Start writing..."}
      />
      <button>Add Chapter</button>
    </Container>
  );
};

export default EditChapter;
